-- First, get the protocol ID
SET @protocol_id = (SELECT id FROM protocols LIMIT 1);
SET @trial_id = (SELECT trialId FROM protocols LIMIT 1);

-- Create task scaffold
INSERT INTO taskScaffolds (protocolId, trialId, status, createdAt, updatedAt)
VALUES (@protocol_id, @trial_id, 'draft', NOW(), NOW());

SET @scaffold_id = LAST_INSERT_ID();

-- Create phases (sections in the Protocol Map)
INSERT INTO phases (scaffoldId, name, color, orderIndex, createdAt, updatedAt) VALUES
(@scaffold_id, 'Screening Phase', '#3B82F6', 1, NOW(), NOW()),
(@scaffold_id, 'Treatment Phase', '#10B981', 2, NOW(), NOW()),
(@scaffold_id, 'Follow-up Phase', '#F59E0B', 3, NOW(), NOW()),
(@scaffold_id, 'Study Closeout', '#8B5CF6', 4, NOW(), NOW());

-- Get phase IDs
SET @screening_id = (SELECT id FROM phases WHERE scaffoldId = @scaffold_id AND name = 'Screening Phase');
SET @treatment_id = (SELECT id FROM phases WHERE scaffoldId = @scaffold_id AND name = 'Treatment Phase');
SET @followup_id = (SELECT id FROM phases WHERE scaffoldId = @scaffold_id AND name = 'Follow-up Phase');
SET @closeout_id = (SELECT id FROM phases WHERE scaffoldId = @scaffold_id AND name = 'Study Closeout');

-- Create tasks for Screening Phase
INSERT INTO tasks (phaseId, name, duration, orderIndex, status, createdAt, updatedAt) VALUES
