(@screening_id, 'Site Initiation Visit', 5, 2, 'pending', NOW(), NOW()),
(@screening_id, 'Patient Recruitment', 60, 3, 'pending', NOW(), NOW()),
(@screening_id, 'Informed Consent', 1, 4, 'pending', NOW(), NOW()),
(@screening_id, 'Baseline Assessments', 7, 5, 'pending', NOW(), NOW());

-- Create tasks for Treatment Phase
