(@treatment_id, 'Treatment Administration', 84, 3, 'pending', NOW(), NOW()),
(@treatment_id, 'Safety Monitoring', 84, 4, 'pending', NOW(), NOW()),
(@treatment_id, 'Efficacy Assessments', 84, 5, 'pending', NOW(), NOW());

-- Create tasks for Follow-up Phase
INSERT INTO tasks (phaseId, name, duration, orderIndex, status, createdAt, updatedAt) VALUES
(@followup_id, 'End of Treatment Visit', 1, 1, 'pending', NOW(), NOW()),
(@followup_id, 'Follow-up Visits', 90, 2, 'pending', NOW(), NOW()),
(@followup_id, 'Long-term Safety Monitoring', 90, 3, 'pending', NOW(), NOW());

-- Create tasks for Study Closeout
INSERT INTO tasks (phaseId, name, duration, orderIndex, status, createdAt, updatedAt) VALUES
(@closeout_id, 'Data Lock', 14, 1, 'pending', NOW(), NOW()),
(@closeout_id, 'Statistical Analysis', 30, 2, 'pending', NOW(), NOW()),
(@closeout_id, 'Final Study Report', 60, 3, 'pending', NOW(), NOW()),
(@closeout_id, 'Site Closeout Visit', 5, 4, 'pending', NOW(), NOW());

SELECT 'Demo data inserted successfully!' as result;

